#include <vector>
#include <queue>

using namespace std;

class Solution {
public:
    vector<int> loudAndRich(vector<vector<int>>& richer, vector<int>& quiet) {
        int n = quiet.size();
        vector<vector<int>> graph(n);
        vector<int> indegree(n, 0), ans(n);
        for (int i = 0; i < n; ++i) ans[i] = i;

        for (auto& r : richer) {
            graph[r[0]].push_back(r[1]);
            indegree[r[1]]++;
        }

        queue<int> q;
        for (int i = 0; i < n; ++i)
            if (indegree[i] == 0) q.push(i);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : graph[u]) {
                if (quiet[ans[u]] < quiet[ans[v]])
                    ans[v] = ans[u];
                if (--indegree[v] == 0)
                    q.push(v);
            }
        }

        return ans;
    }
};
